import * as React from "react";
import { useEffect } from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import { StaticImage } from "gatsby-plugin-image";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { Company } from "../interfaces";
import data from "../data/data.json";
import Link from "../components/AppLink";
import Layout from "../components/Layout";
import images from "../images";
import SocialProofBar from "../components/SocialProofBar";
import MetricsStrip from "../components/MetricStrip";
import VerticalLinksGrid from "../components/VerticalLinksGrid";
import CaseStudyProofGrid, {
  type CaseStudyProofItem,
  type CaseStudyProofLabels,
} from "../components/CaseStudyProofGrid";
import ClaimEvidencePanel from "../components/ClaimEvidencePanel";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import { trackCtaClick } from "../utils/analytics";
import { getCaseStudyProofSource } from "../utils/caseStudyProof";
import { VERTICAL_ORDER, getVerticalConfig } from "../utils/verticals";

const info: Company = data[0];

type SocialProofTranslation = {
  label: string;
  supportingText?: string;
  chips: Array<{ chip: string }>;
};

const WorkflowIcon: React.FC<{ iconKey: string; alt: string }> = ({
  iconKey,
  alt,
}) => {
  switch (iconKey) {
    case "seo_icon_1":
      return (
        <StaticImage
          src="../images/seo_icon_1.png"
          alt={alt}
          width={64}
          height={64}
          placeholder="blurred"
          formats={["auto", "webp", "avif"]}
          className={styles.icon}
        />
      );
    case "seo_icon_2":
      return (
        <StaticImage
          src="../images/seo_icon_2.png"
          alt={alt}
          width={64}
          height={64}
          placeholder="blurred"
          formats={["auto", "webp", "avif"]}
          className={styles.icon}
        />
      );
    case "seo_icon_3":
      return (
        <StaticImage
          src="../images/seo_icon_3.png"
          alt={alt}
          width={64}
          height={64}
          placeholder="blurred"
          formats={["auto", "webp", "avif"]}
          className={styles.icon}
        />
      );
    default:
      return (
        <StaticImage
          src="../images/seo_icon_4.png"
          alt={alt}
          width={64}
          height={64}
          placeholder="blurred"
          formats={["auto", "webp", "avif"]}
          className={styles.icon}
        />
      );
  }
};

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const items = info.homePage.items;
  const whatsappHref = info.whatsapp;
  const heroVisual = images.bg_carousel_1 ?? images.bg_workflow ?? images.bg;
  const verticalItems = VERTICAL_ORDER.map((verticalKey) => {
    const config = getVerticalConfig(verticalKey);

    return {
      to: config.path,
      title: t(`verticalsHub.items.${verticalKey}.title`) as string,
      text: t(`verticalsHub.items.${verticalKey}.text`) as string,
    };
  });

  const metricsItems = [
    {
      highlight: t("homePage.metrics.description.0.item"), // Campaign Landing Pages
      title: t("homePage.metrics.items.0.title"),
      description: t("homePage.metrics.items.0.description"),
      href: "/services/web-design-development/",
    },
    {
      highlight: t("homePage.metrics.description.1.item"), // Local SEO Visibility
      title: t("homePage.metrics.items.1.title"),
      description: t("homePage.metrics.items.1.description"),
      href: "/services/seo/",
    },
    {
      highlight: t("homePage.metrics.description.2.item"), // Menu & Catalog Updates
      title: t("homePage.metrics.items.2.title"),
      description: t("homePage.metrics.items.2.description"),
      href: "/services/maintenance/",
    },
    {
      highlight: t("homePage.metrics.description.3.item"), // Tracking & Analytics
      title: t("homePage.metrics.items.3.title"),
      description: t("homePage.metrics.items.3.description"),
      href: "/services/analytics/",
    },
  ];

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);
  const socialProof = t("homePage.socialProof", {
    returnObjects: true,
  }) as SocialProofTranslation;
  const proofLabels = t("proofBlocks.labels", {
    returnObjects: true,
  }) as CaseStudyProofLabels;
  const proofCtaLabel = t("proofBlocks.ctaLabel") as string;
  const chesterCourtProof = getCaseStudyProofSource(t, "chester-court");
  const reefCleaningProof = getCaseStudyProofSource(t, "reef-cleaning-company");
  const envirogunProof = getCaseStudyProofSource(t, "envirogun");
  const proofItems: CaseStudyProofItem[] = [
    {
      client: chesterCourtProof.client,
      businessType: chesterCourtProof.businessType,
      problem:
        chesterCourtProof.challenges[1] || chesterCourtProof.challenges[0] || "",
      intervention:
        chesterCourtProof.interventions[1] ||
        chesterCourtProof.interventions[0] ||
        "",
      result:
        chesterCourtProof.metrics[1]?.value ||
        chesterCourtProof.results[0] ||
        "",
      href: chesterCourtProof.href,
      ctaLabel: proofCtaLabel,
    },
    {
      client: reefCleaningProof.client,
      businessType: reefCleaningProof.businessType,
      problem:
        reefCleaningProof.challenges[1] || reefCleaningProof.challenges[0] || "",
      intervention:
        reefCleaningProof.interventions[1] ||
        reefCleaningProof.interventions[0] ||
        "",
      result:
        reefCleaningProof.metrics[0]?.value || reefCleaningProof.results[0] || "",
      href: reefCleaningProof.href,
      ctaLabel: proofCtaLabel,
    },
    {
      client: envirogunProof.client,
      businessType: envirogunProof.businessType,
      problem: envirogunProof.challenges[0] || "",
      intervention:
        envirogunProof.interventions[1] ||
        envirogunProof.interventions[0] ||
        "",
      result:
        envirogunProof.metrics[1]?.value || envirogunProof.results[0] || "",
      href: envirogunProof.href,
      ctaLabel: proofCtaLabel,
    },
  ].filter(
    (item) =>
      item.client &&
      item.businessType &&
      item.problem &&
      item.intervention &&
      item.result
  );

  const industries = Array.isArray(socialProof?.chips)
    ? socialProof.chips.map((c) => c.chip).filter(Boolean)
    : [];

  return (
    <>
      <Layout data={info}>
        <section className="mx-auto mt-4 grid w-full max-w-6xl items-center gap-8 px-4 sm:mt-10 sm:grid-cols-[minmax(0,1.05fr)_minmax(320px,0.95fr)] sm:px-6">
          <div className="order-2 sm:order-1">
            <h1 className={styles.heroTitle}>{t("hero.title")}</h1>
            <h2 className={styles.heroSubtitle}>{t("hero.subtitle")}</h2>
            <aside className="mx-auto flex max-w-xl flex-col gap-4 sm:mx-0 sm:flex-row">
              <a
                href={info.whatsapp}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-secondary px-4 py-2 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "home_whatsapp_primary",
                    cta_location: "home_hero",
                    destination: info.whatsapp,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("hero.cta")}
              </a>
              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-4 py-2 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "home_email_secondary",
                    cta_location: "home_hero",
                    destination: whatsappHref,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("hero.bookNow")}
              </a>
            </aside>
          </div>

          <div className="order-1 sm:order-2">
            <div className="relative overflow-hidden rounded-[2rem] border border-white/10 bg-darkBg/40 shadow-[0_24px_80px_rgba(0,0,0,0.35)]">
              <img
                src={heroVisual.src}
                alt={heroVisual.alt || "Abstract AI and search strategy visual"}
                className="h-[320px] w-full object-cover object-[28%_center] sm:h-[520px]"
                loading="eager"
                decoding="async"
              />
              <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-darkBg/90 via-darkBg/20 to-transparent" />
              <div className="absolute inset-x-0 bottom-0 p-5 sm:p-8">
                <p className="text-xs font-semibold uppercase tracking-[0.16em] text-secondary">
                  SEO + AI Search + Websites
                </p>
                <p className="mt-3 max-w-md text-sm sm:text-base text-light/80">
                  Strategy, structure, and conversion work better when the site
                  feels as intentional as the message.
                </p>
              </div>
            </div>
          </div>
        </section>

        <ClaimEvidencePanel
          snippetKey="claims.home.primary"
          maxWidthClassName="max-w-[1024px]"
        />

        <section className="my-8 sm:my-32 max-w-[1024px] mx-auto">
          {/* // Industries (recomendado al inicio) */}
          <section>
            {socialProof?.label && industries.length > 0 ? (
              <SocialProofBar
                label={socialProof.label}
                supportingText={socialProof.supportingText}
                variant="industries"
                industries={industries}
              />
            ) : null}
          </section>

          {/* // Logos (cuando tengas permisos/activos) */}
          {/* <SocialProofBar
            label="Trusted by"
            variant="logos"
            logos={[
              { src: "/logos/chester-court.svg", alt: "Chester Court" },
              { src: "/logos/reef-cleaning.svg", alt: "Reef Cleaning Company", href: "https://reefcleaningcompany.com" },
              ]}
              /> */}
        </section>
        <section className="my-8 max-w-[1024px] mx-auto">
          <div className="rounded-2xl border border-black/10 bg-primary/70 p-6 text-light shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur">
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
              {t("homePage.industryPath.eyebrow")}
            </p>
            <h2 className="mt-2 text-2xl sm:text-3xl poppins-regular text-verde">
              {t("homePage.industryPath.title")}
            </h2>
            <p className="mt-3 max-w-3xl text-sm sm:text-base text-light/75">
              {t("homePage.industryPath.text")}
            </p>
            <div className="mt-6 flex flex-wrap gap-3">
              <Link
                to="/contractors/"
                className="rounded-full bg-secondary px-4 py-2 text-light"
              >
                {t("homePage.industryPath.primaryCta")}
              </Link>
              <Link
                to="/services/web-design-development/"
                className="rounded-full border border-white/15 bg-white/10 px-4 py-2 text-light/90"
              >
                {t("homePage.industryPath.secondaryCta")}
              </Link>
            </div>
          </div>
        </section>

        <VerticalLinksGrid
          eyebrow={t("verticalsHub.eyebrow") as string}
          title={t("verticalsHub.title") as string}
          subtitle={t("verticalsHub.subtitle") as string}
          items={verticalItems}
          ctaLabel={t("verticalsHub.ctaLabel") as string}
        />

        <section className="my-8 sm:my-32 max-w-[1024px] mx-auto">
          <MetricsStrip
            label={t("homePage.metrics.label") || undefined}
            items={metricsItems}
            compact
          />
        </section>

        <CaseStudyProofGrid
          title={t("homePage.proof.title") as string}
          subtitle={t("homePage.proof.subtitle") as string}
          labels={proofLabels}
          items={proofItems}
        />

        <section className={styles.workflowWrapper} id={info?.menu[2]}>
          <div className="mx-auto max-w-6xl px-4 sm:px-6 py-6">
            <div className="text-center">
              <h3 className={styles.sectionTitles}>{t("keywords.optimization")}</h3>
            </div>
            <div className="mt-8 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
              {items.map((item, index) => {
                const iconKey = `seo_icon_${index + 1}` as keyof typeof images;
                return (
                  <article key={index} className={styles.workflowCard}>
                    <p className="mb-4 text-center text-2xl font-semibold text-light/90">
                      {t(`homePage.${item.title}`)}
                    </p>
                    {item.copy ? (
                      <div className="flex flex-1 flex-col items-center text-center">
                        <WorkflowIcon
                          iconKey={iconKey}
                          alt={images[iconKey].alt}
                        />
                        <p className="mt-2 text-base leading-relaxed text-light/80">
                          {t(`homePage.${item.copy}`)}
                        </p>
                      </div>
                    ) : null}
                  </article>
                );
              })}
            </div>
          </div>
        </section>
      </Layout>
    </>
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <SEO
      data={info}
      titleKey="homePage.metaTitle"
      descriptionKey="homePage.metaDescription"
      pathname="/"
      schemaType="ProfessionalService"
      includeLocalBusinessDetails
    />
  </I18nHeadProvider>
);

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  heroTitle:
    "text-3xl sm:text-5xl poppins-bold text-light text-center sm:text-left mb-4 max-w-4xl mx-auto sm:mx-0",
  heroSubtitle:
    "text-xl sm:text-2xl poppins-regular text-light text-center sm:text-left mb-8 mx-auto sm:mx-0 max-w-4xl",
  sectionTitles: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  workflowWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 sm:mt-36 bg-darkBg/50",
  workflowCard:
    "flex h-full flex-col rounded-2xl border border-black/10 bg-secondary/70 p-6 shadow-sm",
  slide1: "top-2/3 left-[10%] sm:left-1/2",
  slide2: "top-1/3 left-[10%]",
  subtitles: "text-md text-center my-4 sm:my-0",
  icon: "w-16 h-16 mx-auto mb-4 opacity-30",
};
