import * as React from "react";
import Link from "./AppLink";

type VerticalLinkItem = {
  to: string;
  title: string;
  text: string;
};

type Props = {
  eyebrow?: string;
  title: string;
  subtitle?: string;
  items: VerticalLinkItem[];
  ctaLabel: string;
};

const VerticalLinksGrid: React.FC<Props> = ({
  eyebrow,
  title,
  subtitle,
  items,
  ctaLabel,
}) => {
  if (!items.length) return null;

  return (
    <section className="py-10 sm:py-14">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
        <div className="mx-auto max-w-4xl text-center">
          {eyebrow ? (
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-2 text-2xl sm:text-4xl poppins-regular text-verde">
            {title}
          </h2>
          {subtitle ? (
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {subtitle}
            </p>
          ) : null}
        </div>

        <div className="mt-8 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
          {items.map((item) => (
            <article
              key={item.to}
              className="rounded-3xl border border-white/15 bg-white/5 p-6"
            >
              <h3 className="text-lg font-semibold text-light/90">
                {item.title}
              </h3>
              <p className="mt-3 text-sm text-light/75 leading-relaxed">
                {item.text}
              </p>
              <div className="mt-6">
                <Link
                  to={item.to}
                  className="inline-flex rounded-full bg-secondary px-4 py-2 text-light text-sm text-center"
                >
                  {ctaLabel}
                </Link>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default VerticalLinksGrid;
